func (s *Server) handlePageSettingsPOSTCloseSession(
	w http.ResponseWriter, r *http.Request,
) {
	sess, sessToken, ok := s.ReadSession(w, r)
	if !ok {
		return
	}

	var path datapages.Path[struct {
		Token string `path:"token"`
	}]
	path.Values.Token = r.PathValue("token")

	dispatchSessionClosed := dispatcherEventSessionClosed{s: s, ctx: r.Context()}
	p := app.PageSettings{
		App: s.app,
		Base: app.Base{
			App: s.app,
		},
	}
	closeSession, redirect, err := p.POSTCloseSession(r, sess, path, dispatchSessionClosed)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageSettings.CloseSession", err)
		return
	}
	if closeSession {
		if err := s.CloseSession(w, r, sessToken); err != nil {
			s.httpErrIntern(w, r, nil, "removing session", err)
			return
		}
	}
	if httpserve.Redirect(w, r, redirect) {
		return
	}
}

